package com.campus.registration.report; import com.campus.registration.model.*;import com.campus.registration.repository.*; public class ReportService{final CourseRepository c;final RegistrationRepository r;public ReportService(CourseRepository c,RegistrationRepository r){this.c=c;this.r=r;}public void printTimetable(String st)throws Exception{System.out.println("\nPERSONAL TIMETABLE");for(Section s:r.timetable(st))System.out.printf("%s Sec %s | %s %02d:00-%02d:00 | %s%n",s.courseCode(),s.section(),s.day(),s.start(),s.end(),s.room());}public void printSeatUtilization()throws Exception{System.out.println("\nSEAT UTILIZATION");for(Course x:c.all())System.out.printf("%s - %s: %d/%d seats%n",x.code(),x.name(),r.count(x.code()),x.capacity());}public void printClashLogs()throws Exception{System.out.println("\nCLASH LOGS");r.clashLogs().forEach(System.out::println);}}